-- ====================================================================================
-- BSB PICKLEBALL CLUB - DEMO SEED DATA
-- Chứa 6 sân tiêu chuẩn, 5 CLB đang hoạt động + 1 CLB tạm ngưng, 12 Lịch đặt đủ 5 loại
-- ====================================================================================

-- 1. Seed Courts
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, hourly_rate_normal = EXCLUDED.hourly_rate_normal;

-- 2. Seed Clubs (5 Active + 1 Inactive)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, status = EXCLUDED.status;

-- 3. Seed Bookings (12 Lịch đặt đủ 5 loại: CLB, Minitour, Cố định, Vãng lai, Sự kiện với vòng đời Check-in / No-Show)
ON CONFLICT (id) DO NOTHING;
